هزینهٔ هر تن این ماه نسبت به ماه قبل 20٪ بالا رفته در حالی که نرخ سوخت تغییری نداشته. دقیقاً کجای زنجیرهٔ هزینه شکسته؟ (مدیر تولید معدن — معدن مس دره‌زار)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    },
    {
      "dataset": "haul_report",
      "description": "گزارش حمل: مسافت، تن-کیلومتر و مصرف سوخت کامیون‌ها",
      "dimensions": [
        "route",
        "period"
      ],
      "measures": [
        "distance_km",
        "tons",
        "liter"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_ton",
      "description": "هزینهٔ عملیاتی هر تن",
      "formula": "هزینهٔ کل / تن فرآوری‌شده",
      "unit": "تومان بر تن",
      "dimensions": [
        "component",
        "period"
      ]
    },
    {
      "metric": "fuel_per_ton",
      "description": "مصرف سوخت به‌ازای هر تن",
      "formula": "لیتر مصرفی / تن",
      "unit": "لیتر بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود",
    "تأمین مالی عملیات از محل فروش کنسانتره و تسهیلات بانکی"
  ]
}

