{
  "data_catalog": [
    {
      "dataset": "plant_performance",
      "description": "عملکرد کارخانه: خوراک، کنسانتره، بازیابی",
      "dimensions": [
        "month",
        "line"
      ],
      "measures": [
        "feed_tons",
        "concentrate_tons",
        "recovery_pct"
      ]
